const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const rawBody = $input.first().json.rawBody || JSON.stringify($input.first().json.body);
const body = $input.first().json.body;

const signatureHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
const timestampHeader = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;

if (!secret) {
  throw new Error('N8N_WEBHOOK_HMAC_SECRET environment variable is missing.');
}

if (!signatureHeader || !timestampHeader) {
  throw new Error('Unauthorized: Missing signature or timestamp header.');
}

const timestamp = parseInt(timestampHeader, 10);
const now = Date.now();
if (isNaN(timestamp) || Math.abs(now - timestamp) > 300000) {
  throw new Error('Unauthorized: Request timestamp expired or outside 5-minute tolerance.');
}

const expectedSignature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
const receivedHex = signatureHeader.replace(/^sha256=/, '').trim();

if (receivedHex.length !== expectedSignature.length || !crypto.timingSafeEqual(Buffer.from(receivedHex, 'hex'), Buffer.from(expectedSignature, 'hex'))) {
  throw new Error('Unauthorized: HMAC signature mismatch. Payload may have been tampered with.');
}

const eventType = body.eventType;
const isApproved = eventType === 'borrow_request.approved' || eventType === 'loan.created';
const isDeclined = eventType === 'borrow_request.declined';

if (!isApproved && !isDeclined) {
  throw new Error(`Routing Error: Invalid decision event type ${eventType} sent to Workflow B.`);
}

const borrowerEmail = body.data.borrower ? body.data.borrower.email : null;
const borrowerName = body.data.borrower ? body.data.borrower.displayName : 'Borrower';
const lenderName = body.data.lender ? body.data.lender.displayName : 'Lender';
const toolName = body.data.tool ? body.data.tool.name : 'Requested Tool';

const subject = isApproved
  ? `Great News! Your request for ${toolName} was approved`
  : `Update on your borrow request for ${toolName}`;

const emailBody = isApproved
  ? `Hi ${borrowerName},\n\n${lenderName} has approved your borrow request for "${toolName}" from ${body.data.startDate} to ${body.data.endDate}.\n\nPlease coordinate pickup details with your neighbor in LendLoop.`
  : `Hi ${borrowerName},\n\n${lenderName} was unable to fulfill your borrow request for "${toolName}" for the requested dates (${body.data.startDate} to ${body.data.endDate}).\n\nCheck LendLoop for other available tools in your neighborhood.`;

return {
  eventId: body.eventId,
  requestId: body.data.requestId,
  loanId: body.data.loanId || null,
  eventType,
  decision: isApproved ? 'approved' : 'declined',
  toolName,
  borrowerName,
  borrowerEmail,
  recipientUserId: body.data.borrower ? body.data.borrower._id : null,
  subject,
  emailBody,
  idempotencyKey: `notif:${isApproved ? 'req_approved' : 'req_declined'}:${body.data.requestId}`
};

const crypto = require('crypto');
const extractData = $node["Verify HMAC & Parse Decision"].json;
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;
const timestamp = Date.now().toString();

const summary = `Notification email sent to borrower (${extractData.borrowerEmail}) for decision '${extractData.decision}' on request ${extractData.requestId}`;

const writeback = {
  idempotencyKey: extractData.idempotencyKey,
  requestId: extractData.requestId,
  loanId: extractData.loanId || undefined,
  eventType: extractData.eventType,
  recipientUserId: extractData.recipientUserId,
  result: 'sent',
  summary
};

const rawBody = JSON.stringify(writeback);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return {
  signature: `sha256=${signature}`,
  timestamp,
  body: rawBody,
  summary,
  result: 'sent'
};

const crypto = require('crypto');
const extractData = $node["Verify HMAC & Parse Decision"].json;
const currentInput = $input.first().json;
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;
const timestamp = Date.now().toString();

const hasEmail = Boolean(extractData.borrowerEmail && extractData.borrowerEmail.trim());
const errorMsg = currentInput.error ? (currentInput.error.message || JSON.stringify(currentInput.error)) : null;

const summary = !hasEmail
  ? "Notification skipped: Borrower email address not configured."
  : errorMsg
  ? `SMTP provider delivery failed for decision notice: ${errorMsg.slice(0, 200)}`
  : "SMTP provider delivery failed for decision notice.";

const writeback = {
  idempotencyKey: extractData.idempotencyKey,
  requestId: extractData.requestId,
  loanId: extractData.loanId || undefined,
  eventType: extractData.eventType,
  recipientUserId: extractData.recipientUserId,
  result: 'failed',
  summary
};

const rawBody = JSON.stringify(writeback);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return {
  signature: `sha256=${signature}`,
  timestamp,
  body: rawBody,
  summary,
  result: 'failed'
};

let originalResult = 'failed';
let originalSummary = 'Notification delivery failed.';

try {
  const successData = $node["Sign Success Write-Back"].json;
  if (successData && successData.result === 'sent') {
    originalResult = 'sent';
    originalSummary = successData.summary;
  }
} catch (e) {
  // Sign Success Write-Back did not execute
}

if (originalResult !== 'sent') {
  try {
    const failureData = $node["Sign Failure Write-Back"].json;
    if (failureData) {
      originalSummary = failureData.summary || 'Notification delivery failed.';
    }
  } catch (e) {
    // Sign Failure Write-Back did not execute
  }
}

const writebackResponse = $input.first().json || {};
const writebackOk = Boolean(writebackResponse.success === true);

if (originalResult === 'sent' && writebackOk) {
  return {
    delivered: true,
    result: 'sent',
    summary: originalSummary
  };
} else {
  const failureSummary = !writebackOk && originalResult === 'sent'
    ? `Delivery succeeded but Convex activity writeback failed: ${JSON.stringify(writebackResponse)}`
    : originalSummary;
  return {
    delivered: false,
    result: 'failed',
    summary: failureSummary
  };
}
